import "glacia/styles.css";
// Glacia — spinner
// Copied with `npx glacia add spinner`. Edit freely; it is yours.
// Shared helpers come from the `glacia` package, which must be installed.

import {
  forwardRef,
  type HTMLAttributes,
} from "react";
import { cx } from "glacia/internal/cx";

export interface SpinnerProps extends HTMLAttributes<HTMLDivElement> {
  size?: "sm" | "md" | "lg";
}

export const Spinner = forwardRef<HTMLDivElement, SpinnerProps>(function Spinner(
  { className, size = "md", ...props },
  ref,
) {
  return (
    <div
      ref={ref}
      role="status"
      aria-label="Loading"
      className={cx("gl-spinner", className)}
      data-size={size}
      {...props}
    >
      <span className="gl-spinner-ring" />
    </div>
  );
});
